using MediatR;
using TheMathAndScienceAcademy.Application.Abstractions;
using TheMathAndScienceAcademy.Application.Common;
using TheMathAndScienceAcademy.Domain.Entities;
using TheMathAndScienceAcademy.Domain.Repositories;

namespace TheMathAndScienceAcademy.Application.Features.Subjects;
public record SubjectDto(Guid Id,string Name,string Code,string? Description,string AcademicYear,string Status,Guid AcademyId,string? AcademyName);
public class CreateSubjectCommand:IRequest<ApiResponse<SubjectDto>>{public string Name{get;set;}="";public string Code{get;set;}="";public string? Description{get;set;}public string AcademicYear{get;set;}="";public string Status{get;set;}="Active";public Guid? AcademyId{get;set;}}
public class UpdateSubjectCommand:CreateSubjectCommand{public Guid Id{get;set;}}
public record DeleteSubjectCommand(Guid Id):IRequest<ApiResponse<bool>>;public record GetSubjectsQuery:IRequest<ApiResponse<List<SubjectDto>>>;public record GetSubjectQuery(Guid Id):IRequest<ApiResponse<SubjectDto>>;
public class SubjectHandlers:ResponseHandler,IRequestHandler<CreateSubjectCommand,ApiResponse<SubjectDto>>,IRequestHandler<UpdateSubjectCommand,ApiResponse<SubjectDto>>,IRequestHandler<DeleteSubjectCommand,ApiResponse<bool>>,IRequestHandler<GetSubjectsQuery,ApiResponse<List<SubjectDto>>>,IRequestHandler<GetSubjectQuery,ApiResponse<SubjectDto>>{
 readonly ISubjectRepository _subjects;readonly IAcademyRepository _academies;readonly IAcademyScopeService _scope;public SubjectHandlers(ISubjectRepository subjects,IAcademyRepository academies,IAcademyScopeService scope){_subjects=subjects;_academies=academies;_scope=scope;}
 public async Task<ApiResponse<SubjectDto>> Handle(CreateSubjectCommand r,CancellationToken c){var a=await Resolve(r.AcademyId);if(a is null)return BadRequest<SubjectDto>(ResponseMessages.AcademySelectionRequired);if(await _subjects.GetDuplicateAsync(a,r.Name.Trim(),r.Code.Trim(),r.AcademicYear.Trim()) is not null)return BadRequest<SubjectDto>(ResponseMessages.SubjectAlreadyExists);var x=await _subjects.CreateAsync(new Subject{Name=r.Name.Trim(),Code=r.Code.Trim().ToUpperInvariant(),Description=Txt(r.Description),AcademicYear=r.AcademicYear.Trim(),Status=Stat(r.Status),AcademyId=a});return Created(await Dto(x!),ResponseMessages.SubjectCreated);}
 public async Task<ApiResponse<SubjectDto>> Handle(UpdateSubjectCommand r,CancellationToken c){var x=await _subjects.GetByIdAsync(r.Id.ToString());if(x is null)return NotFound<SubjectDto>(ResponseMessages.SubjectNotFound);if(!await Can(x.AcademyId))return BadRequest<SubjectDto>(ResponseMessages.Forbidden);if(await _subjects.GetDuplicateAsync(x.AcademyId,r.Name.Trim(),r.Code.Trim(),r.AcademicYear.Trim(),x.Id)is not null)return BadRequest<SubjectDto>(ResponseMessages.SubjectAlreadyExists);x.Name=r.Name.Trim();x.Code=r.Code.Trim().ToUpperInvariant();x.Description=Txt(r.Description);x.AcademicYear=r.AcademicYear.Trim();x.Status=Stat(r.Status);x.UpdatedAt=DateTime.UtcNow;await _subjects.UpdateAsync(x);return Updated(await Dto(x),ResponseMessages.SubjectUpdated);}
 public async Task<ApiResponse<bool>> Handle(DeleteSubjectCommand r,CancellationToken c){var x=await _subjects.GetByIdAsync(r.Id.ToString());if(x is null)return NotFound<bool>(ResponseMessages.SubjectNotFound);if(!await Can(x.AcademyId))return BadRequest<bool>(ResponseMessages.Forbidden);await _subjects.DeleteAsync(x.Id);return Deleted<bool>(ResponseMessages.SubjectDeleted);}
 public async Task<ApiResponse<List<SubjectDto>>> Handle(GetSubjectsQuery r,CancellationToken c){var s=await _scope.GetScopeAsync();if(!s.IsValid||s.AcademyId is null)return BadRequest<List<SubjectDto>>(ResponseMessages.AcademySelectionRequired);var list=new List<SubjectDto>();foreach(var x in await _subjects.GetByAcademyIdAsync(s.AcademyId))list.Add(await Dto(x));return Success(list);}
 public async Task<ApiResponse<SubjectDto>> Handle(GetSubjectQuery r,CancellationToken c){var x=await _subjects.GetByIdAsync(r.Id.ToString());if(x is null)return NotFound<SubjectDto>(ResponseMessages.SubjectNotFound);if(!await Can(x.AcademyId))return BadRequest<SubjectDto>(ResponseMessages.Forbidden);return Success(await Dto(x));}
 async Task<string?> Resolve(Guid? id){var s=await _scope.GetScopeAsync();if(!s.IsValid||s.AcademyId is null)return null;if(id.HasValue&&!id.Value.ToString().Equals(s.AcademyId,StringComparison.OrdinalIgnoreCase))return null;return s.AcademyId;}async Task<bool> Can(string id){var s=await _scope.GetScopeAsync();return s.IsValid&&s.AcademyId==id;}async Task<SubjectDto> Dto(Subject x)=>new(Guid.Parse(x.Id),x.Name,x.Code,x.Description,x.AcademicYear,x.Status,Guid.Parse(x.AcademyId),(await _academies.GetByIdAsync(Guid.Parse(x.AcademyId)))?.Name);static string? Txt(string? x)=>string.IsNullOrWhiteSpace(x)?null:x.Trim();static string Stat(string x)=>x.Equals("Inactive",StringComparison.OrdinalIgnoreCase)?"Inactive":"Active";
}
